  function renderSettings(){host.innerHTML=`${pageTitle('我的手作空间','管理本设备中的布料、作品和备份。')}<div class="settings-grid"><section class="settings-item"><span class="quick-icon">⌂</span><strong style="margin-top:10px">本地保存</strong><p>布料照片、识别结果和作品都保存在当前浏览器的本地数据库中。此原型没有连接云端。</p><button class="button-outline" id="settingsExport">${icon('download')} 导出完整备份</button></section><section class="settings-item"><span class="quick-icon peach">↺</span><strong style="margin-top:10px">恢复备份</strong><p>导入先前导出的 JSON 备份。导入会完整替换当前手作空间中的资料。</p><label class="button-outline" for="importFile">${icon('upload')} 选择备份文件</label><input class="visually-hidden" type="file" id="importFile" accept="application/json,.json"></section><section class="settings-item"><span class="quick-icon pink">✧</span><strong style="margin-top:10px">试用演示内容</strong><p>布库默认从空白开始，避免示例布料影响购物查重。可以按需加入几款示例体验搭配。</p><button class="button-outline" id="loadSeed">添加演示布料和作品</button></section><section class="settings-item"><span class="quick-icon" style="background:#f3f0e9">☁</span><strong style="margin-top:10px">隐私与分享</strong><p>作品默认只保存在当前设备。导出的作品卡不包含购买价格与收纳位置。</p><button class="button-outline" data-go="projects">查看我的作品</button></section></div>`;host.querySelector('#settingsExport').addEventListener('click',exportData);host.querySelector('#importFile').addEventListener('change',e=>importData(e.target.files?.[0]));host.querySelector('#loadSeed').addEventListener('click',loadDemoData)}
  function openModal(title,subtitle,body,footer='',small=false){modalRoot.innerHTML=`<div class="modal ${small?'modal-small':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><div class="modal-header"><div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(subtitle)}</p></div><button class="icon-button" data-close-modal aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div>`;modalRoot.querySelector('[data-close-modal]').addEventListener('click',closeModal);modalRoot.addEventListener('click',e=>{if(e.target===modalRoot)closeModal()},{once:true});document.addEventListener('keydown',escClose,{once:true});setTimeout(()=>modalRoot.querySelector('input,button,select')?.focus(),50)}
