    const maxWidth=Math.min(570,window.innerWidth-94),maxHeight=Math.min(390,window.innerHeight*.48),scale=Math.min(maxWidth/im.width,maxHeight/im.height,1),width=Math.max(140,Math.round(im.width*scale)),height=Math.max(110,Math.round(im.height*scale)),sx=im.width/width,sy=im.height/height;
    let rect={x:width*.08,y:height*.08,w:width*.84,h:height*.84},active=false,mode='draw',handle='',start=null,initial=null,completed=false;
    const getBounds=()=>({x:Math.round(rect.x*sx),y:Math.round(rect.y*sy),w:Math.round(rect.w*sx),h:Math.round(rect.h*sy)});
    const grips=['nw','n','ne','e','se','s','sw','w'].map(pos=>`<span class="crop-handle crop-${pos}" data-resize="${pos}" aria-label="调整选区大小"></span>`).join('');
    const body=`<div class="crop-stage" id="cropStage" style="width:${width}px;height:${height}px"><img src="${src}" alt="裁剪预览" draggable="false"><div class="crop-selection" id="cropSelection">${grips}<span class="crop-size-badge" id="cropSizeBadge"></span></div></div><p class="crop-help">拖动选框移动；拖动圆点缩放选区。也可在图片上拖动，重新框选区域。</p>`;
    openModal('裁出布料区域',`${escapeHTML(fileName)} · 拖动选框选择要识别和保存的区域`,body,`<button class="button-outline" id="useWholeImage">使用整张图</button><button class="button-primary" id="useCrop">${icon('check')} 使用选区</button>`);
    const stage=modalRoot.querySelector('#cropStage'),selection=modalRoot.querySelector('#cropSelection'),badge=modalRoot.querySelector('#cropSizeBadge');
    function paint(){selection.style.left=`${rect.x}px`;selection.style.top=`${rect.y}px`;selection.style.width=`${rect.w}px`;selection.style.height=`${rect.h}px`;const b=getBounds();badge.textContent=`${b.w} × ${b.h} px`}
    function point(e){const r=stage.getBoundingClientRect();return{x:Math.max(0,Math.min(width,e.clientX-r.left)),y:Math.max(0,Math.min(height,e.clientY-r.top))}}
